(() => {
  const btn = name => [...document.querySelectorAll('button')].find(b => b.innerText.trim().toUpperCase() === name), like = btn('CURTIR') || btn('LIKE')
  const card = document.querySelector('.recsCardboard__cards > [aria-hidden=false]')
  const full = document.body ? document.body.innerText : '', stack = document.querySelector('.recsCardboard__cards')
  // o texto dos perfis (bio etc.) não pode disparar os detectores: "já deu match" numa bio não é a tela de match
  let text = stack ? full.replace(stack.innerText, '') : full
  const dialogs = [...document.querySelectorAll('[role=dialog]')]
  const visible = d => d.checkVisibility({ visibilityProperty: true, opacityProperty: true }) && d.innerText.trim()
  for (const d of dialogs) if (!visible(d)) text = text.replace(d.innerText, '')
  return {
    url: location.href, text, full,
    snap: card ? card.innerText : text, // carta do topo; sem ela, a página inteira
    ready: (!like || !like.disabled) && (!!card || !document.querySelector('.recsCardboard__cards')),
    // o Tinder deixa dialogs escondidos (visibility:hidden) na página: só conta o que aparece de verdade
    dialog: dialogs.some(visible)
  }
})()

