Add-Type -AssemblyName System.Device; $w = New-Object System.Device.Location.GeoCoordinateWatcher;
$null = $w.TryStart($false, [TimeSpan]::FromSeconds(10)); $t = (Get-Date).AddSeconds(10)
while ($w.Position.Location.IsUnknown -and (Get-Date) -lt $t) { Start-Sleep -Milliseconds 200 }
$l = $w.Position.Location; $c = [cultureinfo]::InvariantCulture
if (-not $l.IsUnknown) { '{"lat":' + $l.Latitude.ToString($c) + ',"lon":' + $l.Longitude.ToString($c) + ',"acc":' + $l.HorizontalAccuracy.ToString($c) + '}' }
